toolArgs.file_text:
.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 1.5rem;
}

/* Step Indicator */
.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-indicator li {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #ddd;
    font-size: 0.85rem;
}

.step-indicator li.active {
    border-bottom-color: #0d6efd;
    font-weight: 600;
    color: #0d6efd;
}

.step-indicator li.completed {
    border-bottom-color: #198754;
    color: #198754;
}

.step-indicator li.future {
    color: #999;
}

.step-indicator button {
    background: none;
    border: none;
    cursor: pointer;
    color: inherit;
    font: inherit;
    padding: 0;
}

.step-indicator button:hover {
    text-decoration: underline;
}

.step-icon {
    display: block;
    font-size: 1.1rem;
    margin-bottom: 0.25rem;
}

.step-content {
    display: contents;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-next, .btn-submit {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #0b5ed7;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-back {
    background: #f8f9fa;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-back:hover {
    background: #e9ecef;
}

.btn-add {
    background: none;
    border: 1px dashed #0d6efd;
    color: #0d6efd;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background: #f0f7ff;
}

.btn-remove {
    background: none;
    border: none;
    color: #dc3545;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-edit {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit:hover {
    text-decoration: underline;
}

/* Cards */
.work-entry-card, .reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry-header, .reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry-header h4, .reference-header h4 {
    margin: 0;
}

/* Messages */
.error-message {
    background: #f8d7da;
    color: #842029;
    padding: 0.75rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
}

.char-count {
    text-align: right;
    color: #666;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Review */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-entry:last-child {
    border-bottom: none;
}

.date-range {
    color: #666;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
    background: #d1e7dd;
    border-radius: 8px;
}

.confirmation h3 {
    color: #198754;
    margin-bottom: 1rem;
}

