    private bool IsCurrent => Entry.IsCurrent;
    private string StartDateString => Entry.StartDate.ToString("yyyy-MM-dd");
    private string EndDateString => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void Update(WorkEntryModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (DateTime.TryParse(val, out var date))
        {
            Update(Entry with { StartDate = date });
        }
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (string.IsNullOrEmpty(val))
        {
            Update(Entry with { EndDate = null });
        }
        else if (DateTime.TryParse(val, out var date))
        {
            Update(Entry with { EndDate = date });
        }
    }

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }
}

